'use client';

import { useState, useEffect } from 'react';
import { ItemCard } from '@/components/item-card';
import { getItems } from '@/lib/mock-data';
import type { Item } from '@/lib/types';
import { Button } from '@/components/ui/button';
import Link from 'next/link';
import { PlusCircle } from 'lucide-react';
import { cn } from '@/lib/utils';

export default function Home() {
  const [allItems, setAllItems] = useState<Item[]>([]);
  const [activeTab, setActiveTab] = useState<'lost' | 'found'>('lost');

  useEffect(() => {
    const fetchItems = async () => {
      const items = await getItems();
      setAllItems(items);
    };
    fetchItems();
  }, []);

  const filteredItems = allItems.filter((item) => item.status === activeTab);

  return (
    <div>
      <div className="bg-slate-50 py-12">
        <div className="container mx-auto max-w-7xl px-4 text-center">
          <h1 className="text-4xl font-bold tracking-tight text-gray-900 sm:text-5xl">
            Find What You've Lost
          </h1>
          <p className="mt-4 text-lg text-gray-600">
            A community-driven platform to report and recover lost items.
          </p>
        </div>
      </div>

      <div className="container mx-auto max-w-7xl px-4 py-8">
        <div className="mb-8 flex w-full rounded-full bg-gray-200 p-1">
          <button
            onClick={() => setActiveTab('lost')}
            className={cn(
              'w-1/2 rounded-full py-2.5 text-sm font-medium transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
              activeTab === 'lost'
                ? 'bg-card text-card-foreground'
                : 'text-muted-foreground hover:bg-card/50'
            )}
          >
            Lost Items
          </button>
          <button
            onClick={() => setActiveTab('found')}
            className={cn(
              'w-1/2 rounded-full py-2.5 text-sm font-medium transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
              activeTab === 'found'
                ? 'bg-card text-card-foreground'
                : 'text-muted-foreground hover:bg-card/50'
            )}
          >
            Found Items
          </button>
        </div>

        <div className="flex items-center justify-between border-b pb-4">
          <h2 className="text-2xl font-bold tracking-tight">
            Reported as {activeTab === 'lost' ? 'Lost' : 'Found'}
          </h2>
          <Button asChild>
            <Link href={activeTab === 'lost' ? '/report-lost' : '/report-found'}>
              <PlusCircle className="mr-2 h-4 w-4" />
              Report a {activeTab === 'lost' ? 'Lost' : 'Found'} Item
            </Link>
          </Button>
        </div>

        <div className="mt-8 grid gap-6 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
          {filteredItems.map((item) => (
            <ItemCard key={item.id} item={item} />
          ))}
        </div>
      </div>
    </div>
  );
}
